action.command:
cat > /tmp/scan4.mjs <<'EOF'
import fs from "fs";
const s = fs.readFileSync("/opt/node/lib/node_modules/pnpm/dist/pnpm.mjs","utf8");
const lines = s.split("\n");
// find assignments to minimumReleaseAge with a fallback value
for (let n=0;n<lines.length;n++){
  const m = lines[n];
  if (/minimumReleaseAge\s*[:=]/.test(m) && m.includes("??") && !m.includes("undefined") && !m.includes("void")) {
    console.log(n, m.trim().slice(0,160));
  }
}
// find where config security policy keys are read from yaml
for (let n=0;n<lines.length;n++){
  const m = lines[n];
  if (/SECURITY_POLICY_CFG_KEYS/.test(m)) {
    console.log("USE:", n, m.trim().slice(0,160));
  }
}
EOF
node /tmp/scan4.mjs | head -40

